package com.afterglow.player;

import android.content.Context;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.zip.*;

/** Executes packaged native runtimes with argument arrays; never invokes a shell. */
public final class AudioDownloader {
 static volatile String diagnostic="";
 public interface Progress{void update(String message);}
 private final Context context;private volatile Process process;private volatile boolean cancelled;
 public AudioDownloader(Context c){context=c.getApplicationContext();}
 public void cancel(){cancelled=true;Process p=process;if(p!=null)p.destroy();}
 private void ensureRunning()throws IOException{if(cancelled||Thread.currentThread().isInterrupted())throw new IOException("Download cancelled");}
 private String bundledVersion()throws IOException{try(BufferedReader in=new BufferedReader(new InputStreamReader(context.getAssets().open("yt-dlp.version"),"UTF-8"))){return in.readLine();}}
 private void copy(InputStream in,OutputStream out)throws IOException{byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1){ensureRunning();out.write(buffer,0,n);}}
 private void restoreLinks(File dest)throws IOException{String root=dest.getCanonicalPath()+File.separator;try(BufferedReader rows=new BufferedReader(new InputStreamReader(context.getAssets().open("runtime-links.tsv"),"UTF-8"))){String line;while((line=rows.readLine())!=null){String[] parts=line.split("\t",3);if(parts.length!=3||!parts[0].equals(dest.getName()))continue;File link=new File(dest,parts[1]);File target=new File(link.getParentFile(),parts[2]);if(parts[2].startsWith("/")||!link.getCanonicalPath().startsWith(root)||!target.getCanonicalPath().startsWith(root))throw new IOException("Invalid runtime link");if(link.exists()&&!link.delete())throw new IOException("Cannot prepare runtime link");try{android.system.Os.symlink(parts[2],link.getAbsolutePath());}catch(android.system.ErrnoException e){throw new IOException("Cannot create runtime link",e);}}}}
 private void unpack(File archive,File dest)throws IOException{File marker=new File(dest,".ready-links");if(marker.exists())return;dest.mkdirs();String root=dest.getCanonicalPath()+File.separator;try(ZipInputStream zip=new ZipInputStream(new FileInputStream(archive))){ZipEntry entry;while((entry=zip.getNextEntry())!=null){ensureRunning();File file=new File(dest,entry.getName());if(!file.getCanonicalPath().startsWith(root))throw new IOException("Invalid runtime archive path");if(entry.isDirectory()){file.mkdirs();continue;}file.getParentFile().mkdirs();try(OutputStream out=new FileOutputStream(file)){copy(zip,out);}}}restoreLinks(dest);try(OutputStream out=new FileOutputStream(marker)){out.write(1);}}
 File initialize(Progress progress)throws IOException{progress.update("Preparing audio engine…");File base=new File(context.getNoBackupFilesDir(),"audio-engine-v1");base.mkdirs();File nativeDir=new File(context.getApplicationInfo().nativeLibraryDir);unpack(new File(nativeDir,"libpython.zip.so"),new File(base,"python"));unpack(new File(nativeDir,"libffmpeg.zip.so"),new File(base,"ffmpeg"));File script=new File(base,"yt-dlp");String version=bundledVersion();File versionMarker=new File(base,"extractor-"+version);if(!script.exists()||!versionMarker.exists()){File tmp=new File(base,"yt-dlp.tmp");try(InputStream in=context.getAssets().open("yt-dlp");OutputStream out=new FileOutputStream(tmp)){copy(in,out);}if(!tmp.renameTo(script))throw new IOException("Cannot initialize extractor");try(OutputStream marker=new FileOutputStream(versionMarker)){marker.write(1);}}return base;}
 public String version()throws Exception{File base=initialize(m->{});return execute(base,Arrays.asList("--version"),m->{});}
 private String execute(File base,List<String> args,Progress progress)throws Exception{ensureRunning();File nativeDir=new File(context.getApplicationInfo().nativeLibraryDir);ArrayList<String> cmd=new ArrayList<>();cmd.add(new File(nativeDir,"libpython.so").getAbsolutePath());cmd.add(new File(base,"yt-dlp").getAbsolutePath());cmd.addAll(args);ProcessBuilder builder=new ProcessBuilder(cmd).redirectErrorStream(true);Map<String,String> env=builder.environment();env.put("LD_LIBRARY_PATH",new File(base,"python/usr/lib").getAbsolutePath()+":"+new File(base,"ffmpeg/usr/lib").getAbsolutePath());env.put("PYTHONHOME",new File(base,"python/usr").getAbsolutePath());env.put("SSL_CERT_FILE",new File(base,"python/usr/etc/tls/cert.pem").getAbsolutePath());env.put("TMPDIR",context.getCacheDir().getAbsolutePath());env.put("PATH",System.getenv("PATH")+":"+nativeDir.getAbsolutePath());env.put("PYTHONUNBUFFERED","1");process=builder.start();Process current=process;ScheduledExecutorService watchdog=Executors.newSingleThreadScheduledExecutor();ScheduledFuture<?> deadline=watchdog.schedule(()->current.destroy(),10,TimeUnit.MINUTES);StringBuilder tail=new StringBuilder();try(BufferedReader reader=new BufferedReader(new InputStreamReader(current.getInputStream()))){String line;while((line=reader.readLine())!=null){ensureRunning();tail.append(line).append('\n');if(tail.length()>16000)tail.delete(0,tail.length()-16000);if(line.startsWith("AG_PROGRESS:"))progress.update("Downloading audio · "+line.substring(12).trim());else if(line.contains("[ExtractAudio]")||line.contains("[Fixup"))progress.update("Preparing track for native playback…");}int exit=current.waitFor();ensureRunning();if(exit!=0){diagnostic=tail.toString().replaceAll("https?://[^\\s]+","[URL]");String detail=tail.toString().toLowerCase(Locale.US);if(detail.contains("sign in")||detail.contains("not a bot"))throw new IOException("YouTube requires verification for this track. No audio was cached.");if(detail.contains("private")||detail.contains("unavailable")||detail.contains("copyright"))throw new IOException("This track is unavailable for downloading.");if(detail.contains("403")||detail.contains("po token"))throw new IOException("YouTube rejected this download. Try another track; the extractor may need an update.");if(detail.contains("certificate"))throw new IOException("Secure connection failed. Check your phone's date and network.");throw new IOException("Audio download failed. Check your connection or try another track.");}return tail.toString().trim();}finally{deadline.cancel(false);watchdog.shutdownNow();if(current.isAlive())current.destroy();process=null;}}
 public File download(String id,Progress progress)throws Exception{if(id==null||!id.matches("[A-Za-z0-9_-]{11}"))throw new IOException("Invalid YouTube track");File existing=AudioCache.find(context,id);if(existing!=null){existing.setLastModified(System.currentTimeMillis());return existing;}File base=initialize(progress);PartialDownloads.prune(context,id);File work=new File(context.getCacheDir(),"audio-download-"+id);work.mkdirs();File preserve=PlaybackService.instance!=null?AudioCache.find(context,PlaybackService.instance.current().uri):null;AudioCache.trim(context,preserve,150L*1024*1024);if(context.getCacheDir().getUsableSpace()<200L*1024*1024)throw new IOException("Free at least 200 MB on your phone before downloading.");File nativeDir=new File(context.getApplicationInfo().nativeLibraryDir);boolean complete=false;try{progress.update("Resolving audio (resuming if available)…");execute(base,Arrays.asList("--ignore-config","--no-playlist","--no-cache-dir","--no-mtime","--newline","--socket-timeout","20","--continue","--part","--concurrent-fragments","2","--abort-on-unavailable-fragments","--retries","5","--fragment-retries","5","--max-filesize","150M","--js-runtimes","quickjs:"+new File(nativeDir,"libqjs.so").getAbsolutePath(),"--ffmpeg-location",new File(nativeDir,"libffmpeg.so").getAbsolutePath(),"-f","bestaudio[ext=m4a]/bestaudio","-x","--audio-format","best","--progress-template","download:AG_PROGRESS:%(progress._percent_str)s","-o",new File(work,id+".%(format_id)s.%(ext)s").getAbsolutePath(),"https://www.youtube.com/watch?v="+id),progress);ensureRunning();File found=null;File[] candidates=work.listFiles();if(candidates!=null)for(File f:candidates)if(f.getName().matches(java.util.regex.Pattern.quote(id)+"\\.[A-Za-z0-9_-]+\\.(m4a|opus|mp3|ogg|aac|flac|wav|webm)")&&f.length()>0){found=f;break;}if(found==null)throw new IOException("No playable audio was returned.");if(found.length()>150L*1024*1024)throw new IOException("Track exceeds the 150 MB limit.");android.media.MediaMetadataRetriever metadata=new android.media.MediaMetadataRetriever();try{metadata.setDataSource(found.getAbsolutePath());String duration=metadata.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_DURATION);if(duration==null||Long.parseLong(duration)<=0)throw new IOException("Downloaded audio could not be verified.");}finally{metadata.release();}File target=new File(AudioCache.directory(context),id+found.getName().substring(found.getName().lastIndexOf('.')));AudioCache.trim(context,preserve,found.length());if(AudioCache.size(context)+found.length()>AudioCache.LIMIT)throw new IOException("Cache is full. Clear cached tracks in Settings.");if(!found.renameTo(target))throw new IOException("Cannot save cached track");complete=true;return target;}finally{if(complete||PlaybackService.deletedCacheIds.contains(id))PartialDownloads.remove(context,id);else work.setLastModified(System.currentTimeMillis());}}
}




